SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @ConfigVersionId uniqueidentifier;
SELECT @ConfigVersionId = config_version_id FROM config.ConfigVersions WHERE version_code = 'CFG-1001.0';
IF @ConfigVersionId IS NULL
BEGIN
    SET @ConfigVersionId = NEWID();
    INSERT config.ConfigVersions(config_version_id, version_code, status_code, description, published_at_utc, effective_from_utc)
    VALUES(@ConfigVersionId, 'CFG-1001.0', 'PUBLISHED', N'Schedule-first strategy ported from Dan_Recomp v64', SYSUTCDATETIME(), SYSUTCDATETIME());
END;

DELETE FROM config.PlanDefinitions WHERE config_version_id = @ConfigVersionId;
DELETE FROM config.WorkoutTypeDefinitions WHERE config_version_id = @ConfigVersionId;
DELETE FROM config.GlobalSettings WHERE config_version_id = @ConfigVersionId;

INSERT config.PlanDefinitions(config_version_id,plan_code,display_name,base_rest_carbs_g,plan_category_code,sort_order,is_active) VALUES(@ConfigVersionId,N'PLAN_1',N'Plan 1 - Health Reset',100,N'HEALTH_RESET',1,1);
